<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';const form=useForm({email:'',password:'',remember:false});</script><template><Head title="Sign in"/><main class="grid min-h-screen lg:grid-cols-2"><section class="relative hidden overflow-hidden bg-ink p-14 text-white lg:flex lg:flex-col lg:justify-between"><div class="font-display text-2xl font-bold">Lens<span class="text-indigo-400">Pic</span></div><div><p class="eyebrow text-indigo-300">Made for photographers</p><h1 class="mt-4 max-w-lg font-display text-5xl font-bold leading-tight">Every moment, delivered with intention.</h1><p class="mt-5 max-w-md text-white/55">Private event galleries, durable processing and consent-led photo discovery.</p></div><p class="text-xs text-white/35">Original LensPic experience</p></section><section class="flex items-center justify-center p-6"><form class="w-full max-w-md" @submit.prevent="form.post('/login')"><p class="eyebrow">Welcome back</p><h2 class="mt-3 font-display text-3xl font-bold">Sign in to your studio</h2><label class="mt-8 block text-sm font-semibold">Email<input v-model="form.email" type="email" class="field mt-2" required></label><p v-if="form.errors.email" class="mt-1 text-sm text-coral">{{form.errors.email}}</p><label class="mt-5 block text-sm font-semibold">Password<input v-model="form.password" type="password" class="field mt-2" required></label><label class="mt-4 flex gap-2 text-sm"><input v-model="form.remember" type="checkbox">Keep me signed in</label><button class="btn-primary mt-6 w-full" :disabled="form.processing">{{form.processing?'Signing in…':'Sign in'}}</button><p class="mt-6 text-center text-sm text-black/50">New to LensPic? <Link href="/register" class="font-semibold text-indigo">Create an account</Link></p></form></section></main></template>
